def solve(tokens, spans, limit):
    if type(limit) is not int or limit<1: raise ValueError('limit')
    end=0
    for a,b in spans:
        if type(a) is not int or type(b) is not int or not 0<=a<b<=len(tokens) or a<end:
            raise ValueError('spans')
        end=b
    labels=[-100]*min(limit,len(tokens))
    for a,b in spans:
        for i in range(a,min(b,len(labels))): labels[i]=tokens[i]
    if not any(x!=-100 for x in labels[1:]): raise ValueError('no causal target')
    return labels

